window.FILM_WORK_PROMPTS={"work_id":"src-887491db1b6e1b88","records":[{"work_id":"src-887491db1b6e1b88","frame_id":"FG-cdaf492d8d354541","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (891).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"画面主体为一张倒置的人脸，面部布满红色液体痕迹，背景右侧可见大量金色褶皱反光材质，人物头部占据画面绝大部分空间。","analysis":"构图极度紧凑，人物面部倒置占据画面左侧及中央，右侧背景为金色褶皱物体。可见范围仅限头部及少许颈部，无全身或肢体动作。光线柔和，皮肤呈现红润色泽，与鲜红液体及金色背景形成色彩层次，无强烈阴影。","prompt":"倒置的人脸特写，面部皮肤红润，鼻孔与嘴角周围流淌着鲜红色液体，液体顺着脸颊向下延伸。人物双眼紧闭，金色卷发散落在头部两侧。画面右侧背景填充着金色褶皱反光材质，呈现出类似金属箔或织物的质感，表面有细碎的高光反射。整体色调偏暖，红色液体与金色背景形成视觉对比，画面充满压抑与不安的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:21:52-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (891).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.497,"observed_resolution":"normal","observation_limits":[],"id":"VP-af2311a5acb9ab9b","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-90a3dcda8bbb1ff3","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (911).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"户外沙地场景，右侧一棵枝叶茂密的大树，树下及周围散落着多名赤裸上身的人物，有的躺卧有的倚靠，左后方站立一人，地面有木凳和散落的衣物。","analysis":"画面采用高角度俯视拍摄，环境占据大部分空间，沙地纹理清晰。右侧大树形成视觉重心，树冠遮蔽部分光线，树下形成阴影区。人物多呈躺卧或半坐姿态，身体大部分可见，衣着极少，仅见红色、蓝色等色块衣物。左后方站立人物全身可见，身形较小。整体光线明亮，色彩偏暖黄，对比度适中，阴影柔和。","prompt":"高角度俯视的户外沙地场景，右侧一棵枝叶繁茂的大树占据画面右半部分，树干粗壮，树冠投下阴影。树下及周围沙地上散落着多名赤裸上身的人物，前景左侧一人俯卧，中间一人侧卧，右侧一人半躺，树下有人倚靠树干，还有一人蜷缩坐着。左后方远处站立一名全身可见的人物，旁边有一个小木凳。地面散落着红色、蓝色等衣物色块。沙地呈浅黄褐色，背景远处有稀疏的绿色植被。光线明亮，整体色调偏暖，阴影柔和，人物皮肤呈现日晒后的色泽。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:22:00-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (911).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.525,"observed_resolution":"normal","observation_limits":[],"id":"VP-40037c282b507511","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-d24594e82dafb940","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (908).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"两名男子在崎岖的岩石荒地上，左侧男子赤裸上身跪坐，右侧男子身着深色古装站立，两人身体靠近，背景为连绵的灰色乱石。","analysis":"画面采用平视视角，构图紧凑。左侧人物呈跪姿，全身可见，肌肉线条清晰；右侧人物站立，占据画面右侧较大比例，身着深色长袍与金属护具。光线为强烈的自然日光，在岩石和人物皮肤上形成高对比度的明暗层次，色彩以岩石的灰白和衣物的深黑为主。","prompt":"在阳光强烈的崎岖岩石荒地上，两名男子近距离互动。左侧男子赤裸上身，仅穿浅色腰布，呈跪姿，身体前倾，双手伸向右侧人物。右侧男子站立，金发，身穿黑色长袍，肩部有带金属圆钉的护具，手臂佩戴宽手镯，身体略微后仰。背景是层层叠叠的灰色乱石，天空呈淡白色。强烈的直射光在人物皮肤和岩石表面投下清晰的阴影，画面质感粗粝，色彩对比鲜明。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:22:08-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (908).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.494,"observed_resolution":"normal","observation_limits":[],"id":"VP-a0591b909d4ce639","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-a3379260f427f17a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (890).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"一名赤裸上身的男子低头注视胸前，双手在胸口位置握持着某种深色物体，背景为斑驳粗糙的暗色墙面，环境昏暗压抑。","analysis":"画面截取人物上半身，头部至胸部区域占据画面主体，右侧留有大面积斑驳墙面。人物呈低头俯视姿态，双手在胸前交握。光线从上方投射，在额头、鼻梁、锁骨及手臂肌肉上形成高光，与周围深暗背景形成强烈明暗对比，整体色调偏冷且带有颗粒感。","prompt":"一名年轻男子赤裸上身，黑色短发，低头向下注视，神情专注。他双手在胸前握持着一个深色物体，手臂肌肉线条清晰，皮肤表面带有光泽。背景是粗糙斑驳的暗色墙面，右侧墙面有明显的剥落纹理。光线从上方投射，照亮人物的额头、鼻梁、锁骨和手臂，形成强烈的明暗对比，整体色调偏冷，画面带有明显的胶片颗粒感，氛围压抑。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:22:15-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (890).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.493,"observed_resolution":"normal","observation_limits":[],"id":"VP-c6698df54626d603","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-ba8a49c78513ace9","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (812).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"在布满碎石的山脊上，多名人物分散站立或蹲坐。部分人物手持长弓，一人背对镜头站立，右侧有一根竖立的木杆，背景是连绵的山脉和灰白天空。","analysis":"画面采用远景构图，人物在画面中占比极小，环境占据主导。视角平视，光线为均匀的漫射光，缺乏强烈的明暗对比。色彩呈现低饱和度的复古胶片质感，天空与远山呈灰蓝色，地面为土黄色碎石，人物衣着颜色各异，包括深色、红色和浅色。","prompt":"这是一张远景视角的户外静帧，画面展现了荒凉的山脊地貌，地面铺满了灰白色的碎石和乱石。多名人物分散站立在画面中景位置，身形在广阔的环境中显得渺小。左侧一人蹲坐，旁边一人站立手持长弓；中间一人站立持弓，另一人背对镜头站立，身穿深色衣物；右侧有一根竖立的木杆，旁边有人影，最右侧一人站立持弓。背景是层叠的远山，天空呈现灰白色，光线柔和均匀，整体色调偏冷且饱和度低，具有复古胶片质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:22:23-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (812).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.482,"observed_resolution":"normal","observation_limits":[],"id":"VP-911ca3a90b6258cc","origin":"visual"}]};